  , ("io-to-st-cast",False,"primitive runST(Int) (/\\(a1 >= bot) -> primitive ioReturn(Int) 7)")
  , ("cross-region-read",False,"/\\(a1 >= bot) -> /\\(a2 >= bot) -> \\(array_1 : STArray a1 Int) -> primitive readSTArray(a2, Int) array_1 0")
  , ("cross-region-write",False,"/\\(a1 >= bot) -> /\\(a2 >= bot) -> \\(array_1 : STArray a1 Int) -> primitive writeSTArray(a2, Int) array_1 0 1")
